"""Interview tasks anchored to a requirement, never invented candidate experience."""
import re

# Each task asks for a decision or a work sample; the guide helps HR assess it.
TASKS = [
 ('inventory', r'инвентаризац', 'При инвентаризации фактический остаток не совпал с учётом. Как проверите причину, какие документы запросите и как зафиксируете расхождение?', 'Последовательность сверки, первичные документы, объяснение расхождений и оформление результата.'),
 ('assets', r'основн\w* средств|\bтмц\b|\bос\b|складск', 'Оборудование передают между подразделениями. Какие данные и документы проверите перед отражением перемещения и как исключите потерю объекта в учёте?', 'Идентификация объекта, ответственные лица, основания перемещения и сверка до/после операции.'),
 ('css', r'css|flexbox|\bgrid\b|псевдокласс|позиционирован', 'Нужно сверстать карточки разной высоты: три колонки на широком экране и одну на телефоне. Где выберете Grid, где Flexbox и как проверите, что длинный текст не ломает сетку?', 'Обоснованный выбор раскладки, ограничения размеров, брейкпоинты и проверка переполнения.'),
 ('vue', r'vue|composition api|v-model', 'В Vue 3 форма вынесена в дочерний компонент. Как передадите данные и изменения через props, emit или v-model, чтобы не менять props напрямую? Где разместите валидацию?', 'Однонаправленный поток данных, контракт компонента, реактивность и разделение ответственности.'),
 ('tailwind', r'tailwind', 'В макете нестандартная палитра и разные отступы для телефона и desktop. Как настроите тему и адаптивные классы Tailwind, чтобы не размножать случайные значения по компонентам?', 'Настройки темы, повторно используемые решения, адаптивные варианты и поддерживаемость.'),
 ('pinia', r'pinia', 'Два Vue-компонента меняют одни данные, а запрос к серверу может завершиться ошибкой. Как организуете store в Pinia, обновление состояния и обработку ошибки?', 'Границы store, actions/state, согласованность данных, загрузка и обработка ошибок.'),
 ('nuxt', r'nuxt|\bssr\b|серверн\w* рендер', 'Страница Nuxt получает данные и использует API браузера. Что выполнится на сервере, что на клиенте и как избежите повторного запроса или ошибки гидратации?', 'Различие SSR/клиента, получение данных и безопасный доступ к browser API.'),
 ('monaco', r'monaco', 'Как встроите Monaco Editor в Vue-компонент, синхронизируете текст с формой и освободите редактор и обработчики при уходе со страницы?', 'Жизненный цикл редактора, контроль изменений и освобождение ресурсов.'),
 ('javascript', r'javascript|\bjs\b|промис|async|\bdom\b|событи', 'Пользователь быстро меняет поисковый запрос, ответы сервера приходят не по порядку. Как не показать устаревший результат и обработать отмену или сетевую ошибку?', 'Порядок асинхронных ответов, отмена/идентификатор запроса и состояния интерфейса.'),
 ('typescript', r'typescript|\bts\b', 'API возвращает несколько вариантов результата, включая ошибку. Как опишете типы и проверите данные на границе приложения без повсеместного any?', 'Типизация разных состояний, сужение типов и проверка внешних данных.'),
 ('html', r'html|семантическ', 'Нужно сделать форму, которой можно пользоваться только клавиатурой. Какие HTML-элементы выберете, как свяжете подписи с полями и покажете ошибку?', 'Семантика формы, label, порядок фокуса и доступные сообщения об ошибках.'),
 ('figma', r'figma|макет', 'В макете не описаны длинные тексты и состояние ошибки. Что уточните у дизайнера до вёрстки и как сверите готовый экран с макетом?', 'Недостающие состояния, размеры/токены и проверка результата.'),
 ('testing', r'тестирован|vitest|jest|кроссбраузер|провер\w*.*верст', 'После изменения компонента ломается только мобильная версия. Как воспроизведёте проблему, локализуете причину и проверите исправление без регрессии?', 'Воспроизводимый сценарий, диагностика, граничные состояния и повторная проверка.'),
 ('code_quality', r'аккурат|читаем|код.стайл|рефактор|git|ревью|code review', 'Вам передали большой компонент с повторяющейся логикой. Что вынесете первым, как сохраните поведение и что попросите проверить на code review?', 'Безопасные границы рефакторинга, понятный контракт и проверка поведения.'),
 ('table', r'excel|sheets|таблиц|больш\w* объем', 'В таблице несколько тысяч строк, дубли и пропуски. Как подготовите данные, найдёте расхождения и проверите, что итоговый отчёт корректен?', 'Ключи/дубли/пропуски, подходящие формулы или инструменты и контрольные сверки.'),
 ('reporting', r'отчет|статистическ|аналитик', 'Сводный отчёт не сходится с исходными данными. Какие проверки сделаете сначала и как объясните исправление получателю отчёта?', 'Прослеживаемость показателей до источника, проверка формул и понятное объяснение.'),
 ('learning_progress', r'успеваемост|контрольн\w* срез', 'В контрольном срезе успеваемость группы резко снизилась. Какие данные проверите, с кем свяжетесь и какие следующие действия предложите?', 'Проверка качества данных, выяснение причин и конкретный план сопровождения.'),
 ('document_check', r'комплектност|провер\w*.*документ|договор|расчетн|делопроизвод|документовед', 'В пакете документов не хватает приложения, а данные сторон расходятся. Что проверите, что вернёте на уточнение и как проконтролируете исправленный пакет?', 'Чек-лист комплектности, сверка реквизитов, фиксация замечаний и контроль версии.'),
 ('information', r'сбор информац|сбор.*данн', 'Нужно собрать сведения у нескольких источников, но ответы противоречат друг другу. Как определите актуальные данные и зафиксируете, что ещё требует подтверждения?', 'Происхождение/актуальность сведений, проверка противоречий и явные неизвестные.'),
 ('communication', r'коммуника|переписк|взаимодейств|сопровожден|согласован|созвон|команд', 'Несколько организаций одновременно задерживают ответы, а срок общий. Как расставите приоритеты, напомните о запросах и покажете команде текущее состояние?', 'Конкретный способ контроля договорённостей, эскалация и понятная коммуникация.'),
 ('organization', r'ответственн|самоорганиз|планирован|срок', 'Две срочные задачи конфликтуют по срокам. Как определите порядок, согласуете перенос и не потеряете остальные обязательства?', 'Критерии приоритета, согласование ожиданий и контроль исполнения.'),
 ('attention', r'внимательн|детал|монотон|системност|концентрац', 'В повторяющемся потоке документов обнаружилась ошибка. Как проверите уже обработанную часть и измените процесс, чтобы ошибка не повторялась?', 'План повторной проверки и конкретная профилактика, а не обещание быть внимательнее.'),
 ('sql', r'\bsql\b|postgres', 'Нужно посчитать количество записей по группам, включая группы без записей. Как построите запрос и проверите, что JOIN не размножил строки?', 'JOIN, агрегация, NULL и контроль количества строк.'),
 ('python', r'python|pandas|автоматиз|скрипт', 'Повторяющуюся обработку файлов нужно автоматизировать. Как проверите вход, обработаете ошибочный файл и убедитесь, что повторный запуск не портит результат?', 'Валидация, идемпотентность, обработка ошибок и контроль результата.'),
]


def interview_tasks(text, status, requirement_id=None):
    normalized = text.casefold().replace('ё', 'е')
    if re.search(r'личн\w* (?:ноутбук|пк|компьютер)', normalized):
        selected=[('equipment', 'Есть ли у вас компьютер для дистанционной работы и устойчивый доступ к интернету? Что нужно подготовить до начала работы?', 'Фактическая готовность рабочего места, а не вывод по профессии кандидата.')]
    elif re.search(r'образован|высшее|бакалавр|экономическ', normalized) and not re.search(r'образовательн|организац|сфер', normalized):
        selected=[('education', 'Какое образование вы завершили, по какому направлению и какой документ подтверждает квалификацию? Если обучение продолжается, каков текущий статус?', 'Уровень, профиль и завершённость обучения; незавершённое не считать оконченным.')]
    elif re.search(r'очн\w* формат|офис', normalized):
        selected=[('format', 'Подходит ли вам очный формат работы? Какие ограничения по присутствию нужно согласовать заранее?', 'Конкретная доступность для требуемого формата.')]
    elif re.search(r'(?:лет|года?).*(?:основн|тмц)|(?:основн|тмц).*(?:лет|года?)', normalized):
        selected=[('relevant_experience', 'В каких периодах вы лично вели ОС или ТМЦ, какие операции выполняли и сколько длилась именно эта работа? Какие периоды пересекались?', 'Профильные задачи и непересекающиеся периоды; общий стаж не подменяет стаж учёта ОС/ТМЦ.')]
    elif re.search(r'опыт.*\d+\s*(?:лет|год)', normalized):
        selected=[('work_periods', 'Какие периоды работы подтверждают требуемый стаж? Назовите задачи, свою зону ответственности и длительность каждого периода без двойного учёта пересечений.', 'Проверяемые периоды и личные задачи; общий стаж не выводить из одного места работы.')]
    else:
        selected=[(key,question,guide) for key,pattern,question,guide in TASKS if re.search(pattern,normalized)]
        # Specific tool checks take precedence over broad teamwork/education words.
        if any(key in {'vue','css','tailwind','pinia','nuxt','monaco','javascript','typescript','html'} for key,_,_ in selected):
            selected=[item for item in selected if item[0] not in {'communication','organization','attention'}]
        if not selected:
            selected=[('requirement:'+normalized, f'Для роли важно: «{text.rstrip(".")}». С чего начнёте такую задачу, какие данные понадобятся и как проверите результат?', 'Последовательность действий, ограничения и проверяемый результат применительно к этому требованию.')]
    return [{'topic':key,'question':question,'listen_for':guide,
             'follow_up':'Если решали похожую задачу, что сделали лично и чем подтвердили результат?',
             'requirement_id':requirement_id,'requirement':text,'status':status} for key,question,guide in selected]
